-- sql
WITH _hq_raw AS (SELECT "created_at" AS _hq_row_1, "status" AS _hq_row_2, "amount_cents" AS _hq_row_3, NULL AS _hq_row_4, "customer_id" AS _hq_row_5, NULL AS _hq_row_6 FROM "analytics"."orders" WHERE "tenant_id" = $1),
_hq_source AS (SELECT (CASE WHEN pg_typeof(_hq_row_1) = 'date'::regtype THEN (_hq_row_1)::timestamp AT TIME ZONE 'UTC' ELSE (_hq_row_1)::timestamptz END) AS _hq_time, _hq_row_2 AS _hq_d0, _hq_row_3 AS _hq_v0, _hq_row_4 AS _hq_a0, _hq_row_5 AS _hq_v1, _hq_row_6 AS _hq_a1 FROM _hq_raw WHERE (_hq_row_1 IS NOT NULL)),
_hq_bounds AS (SELECT * FROM (SELECT (CASE WHEN CAST($2 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($2 AS text) AS timestamptz) ELSE CAST(CAST($2 AS text) AS timestamp) AT TIME ZONE 'UTC' END) AS _hq_lower) AS _hq_step0 CROSS JOIN LATERAL (SELECT (CASE WHEN CAST($3 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($3 AS text) AS timestamptz) ELSE CAST(CAST($3 AS text) AS timestamp) AT TIME ZONE 'UTC' END) AS _hq_upper) AS _hq_step1 CROSS JOIN LATERAL (SELECT date_trunc('day', _hq_lower, 'UTC') AS _hq_first) AS _hq_step2 CROSS JOIN LATERAL (SELECT date_trunc('day', _hq_upper, 'UTC') AS _hq_last) AS _hq_step3),
_hq_series AS (SELECT (((_hq_first AT TIME ZONE 'UTC') + (generate_series(0, ((((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 + 0 + 0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 + 0 + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_period FROM _hq_bounds),
_hq_scanned AS (SELECT * FROM _hq_source CROSS JOIN _hq_bounds WHERE (_hq_time >= _hq_first AND _hq_time < (((_hq_last AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC')) OR (_hq_time < (((_hq_last AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AND _hq_time >= LEAST(((((((_hq_first AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') - (7) * INTERVAL '1 day') AT TIME ZONE 'UTC'), ((((((_hq_first AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') - (14) * INTERVAL '1 day') AT TIME ZONE 'UTC'), date_trunc('month', _hq_first, 'UTC')))),
_hq_skeleton AS (SELECT * FROM _hq_series CROSS JOIN (SELECT DISTINCT _hq_d0 FROM _hq_scanned) AS _hq_combinations),
_hq_fan0 AS (SELECT *, date_trunc('day', _hq_time, 'UTC') AS _hq_period FROM _hq_scanned WHERE _hq_time >= _hq_lower AND _hq_time <= _hq_upper),
_hq_agg0 AS (SELECT _hq_period, _hq_d0, SUM(_hq_v0) AS _hq_m0 FROM _hq_fan0 WHERE _hq_period BETWEEN _hq_first AND _hq_last GROUP BY _hq_period, _hq_d0),
_hq_fan1 AS (SELECT *, (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (generate_series(0, (((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer) + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_period FROM _hq_scanned),
_hq_agg1 AS (SELECT _hq_period, _hq_d0, SUM(_hq_v0) AS _hq_m1 FROM _hq_fan1 WHERE _hq_period BETWEEN _hq_first AND _hq_last AND _hq_time >= ((((((_hq_period AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') - (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') GROUP BY _hq_period, _hq_d0),
_hq_fan2 AS (SELECT *, (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (generate_series(0, (((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (14) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (14) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer) + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (14) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (14) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_period FROM _hq_scanned),
_hq_agg2 AS (SELECT _hq_period, _hq_d0, COUNT(DISTINCT _hq_v1) AS _hq_m2 FROM _hq_fan2 WHERE _hq_period BETWEEN _hq_first AND _hq_last AND _hq_time >= ((((((_hq_period AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') - (14) * INTERVAL '1 day') AT TIME ZONE 'UTC') GROUP BY _hq_period, _hq_d0),
_hq_fan3 AS (SELECT *, (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (generate_series(0, (((((((date_trunc('month', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (1) * INTERVAL '1 month') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('month', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (1) * INTERVAL '1 month') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer) + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, ((((((date_trunc('month', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (1) * INTERVAL '1 month') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('month', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (1) * INTERVAL '1 month') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_period FROM _hq_scanned),
_hq_agg3 AS (SELECT _hq_period, _hq_d0, SUM(_hq_v0) AS _hq_m3 FROM _hq_fan3 WHERE _hq_period BETWEEN _hq_first AND _hq_last GROUP BY _hq_period, _hq_d0),
_hq_values AS (SELECT (s._hq_period AT TIME ZONE 'UTC') AS period, s._hq_d0 AS "status", m0._hq_m0 AS "revenue", m1._hq_m1 AS "rolling", coalesce(m2._hq_m2, 0) AS "rollingBuyers", m3._hq_m3 AS "monthToDate" FROM _hq_skeleton AS s LEFT JOIN _hq_agg0 AS m0 ON s._hq_period = m0._hq_period AND (s._hq_d0 IS NOT DISTINCT FROM m0._hq_d0) LEFT JOIN _hq_agg1 AS m1 ON s._hq_period = m1._hq_period AND (s._hq_d0 IS NOT DISTINCT FROM m1._hq_d0) LEFT JOIN _hq_agg2 AS m2 ON s._hq_period = m2._hq_period AND (s._hq_d0 IS NOT DISTINCT FROM m2._hq_d0) LEFT JOIN _hq_agg3 AS m3 ON s._hq_period = m3._hq_period AND (s._hq_d0 IS NOT DISTINCT FROM m3._hq_d0)),
_hq_result AS (SELECT "period", "status", "revenue", "rolling", "rollingBuyers", "monthToDate" FROM _hq_values UNION ALL SELECT NULL AS "period", NULL AS "status", NULL AS "revenue", NULL AS "rolling", NULL AS "rollingBuyers", NULL AS "monthToDate" FROM _hq_bounds WHERE 0 + 0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 + 0 + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer) + 0 = 1) SELECT "period", "status", "revenue", "rolling", "rollingBuyers", "monthToDate" FROM _hq_result ORDER BY "period" ASC

